var i=`optimistic-vs-pessimistic-locking`;var s=56;var n={en:[{id:`T056-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Normalization organizes relational tables to reduce unintended redundancy and modification anomalies.`},{id:`B`,text:`Optimistic concurrency checks whether data changed before committing; pessimistic locking reserves exclusive access earlier.`},{id:`C`,text:`Indexes accelerate targeted reads by maintaining auxiliary structures, often at the cost of extra storage and slower writes.`},{id:`D`,text:`Schema evolution changes stored structure while preserving existing data and service compatibility.`}]},{id:`T056-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Use EXPLAIN and measured traces; identify full scans, expensive sorts, N+1 ORM queries and unnecessary columns.`},{id:`B`,text:`Use expand-migrate-contract: add compatible fields, backfill safely, switch readers/writers, then remove old structures after verification.`},{id:`C`,text:`Optimistic locking commonly uses a version column in compare-and-swap updates; on conflict, report or retry with fresh state.`},{id:`D`,text:`1NF uses atomic values in the chosen relational model; 2NF removes partial dependency on a candidate key; 3NF removes problematic transitive dependencies; BCNF tightens determinants; 4NF addresses independent multivalued dependencies; 5NF addresses certain join dependencies.`}]},{id:`T056-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`Two administrators editing a venue description can use version conflict detection.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`Buying the final ticket may require atomic conditional update or tightly controlled locking.`},{id:`B`,text:`Both can be implemented with several database engines depending on needs.`},{id:`C`,text:`Recompute aggregates when reconciliation detects drift.`},{id:`D`,text:`Renaming guest.fullName to firstName and lastName requires a transitional writer or mapper, backfill of old records and validation before deleting the original field.`}]},{id:`T056-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Retrying every optimistic conflict can overwrite user intention; holding a pessimistic lock across network calls creates contention.`},{id:`B`,text:`A 'down' migration is not always safe after new data is written.`},{id:`C`,text:`Duplicate fields can become contradictory under concurrency or missed events.`},{id:`D`,text:`Adding indexes for every field hurts writes and consumes memory.`}]},{id:`T056-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`The right choice depends on conflict frequency, criticality and transaction length.`}]}]},{id:`T056-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`Optimistic locking removes the need to handle update conflicts.`}]}]},{id:`T056-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`A transaction's isolation rules still apply.`}]}]},{id:`T056-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Optimistic concurrency checks whether data changed before committing; pessimistic locking reserves exclusive access earlier.`},{id:`B`,text:`Pessimistic locking never creates deadlocks or long waits.`},{id:`C`,text:`Optimistic locking commonly uses a version column in compare-and-swap updates; on conflict, report or retry with fresh state.`},{id:`D`,text:`Adding an index always improves both reads and writes.`}]},{id:`T056-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A transaction's isolation rules still apply.`},{id:`B`,text:`Optimistic locking removes the need to handle update conflicts.`},{id:`C`,text:`Buying the final ticket may require atomic conditional update or tightly controlled locking.`},{id:`D`,text:`Rolling deployments never need expand-and-contract schema changes.`}]},{id:`T056-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`Two administrators editing a venue description can use version conflict detection.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to inspect query plans before and after candidate indexes for room availability. Require measured latency, write overhead and a rollback plan.`},{id:`B`,text:`Have an agent implement both version-based updates and a locked allocation path. Load-test conflicts, deadlocks and user-facing resolution flows.`},{id:`C`,text:`Ask an agent to optimize a slow product page using a derived rating count. Define update semantics, rebuild procedure and tests for duplicate or delayed events.`},{id:`D`,text:`Ask an agent to plan a zero-downtime column split, with phased deployments, backfill checkpoints, integrity queries, rollback limits and observability.`}]},{id:`T056-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`When must a conflict be shown to the user instead of retried automatically?`}]}]},{id:`T056-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`Two administrators editing a venue description can use version conflict detection.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T056-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`Two administrators editing a venue description can use version conflict detection.`,b:!0},{t:` — propose three checks for `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T056-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`Two administrators editing a venue description can use version conflict detection.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T056-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Optimistic vs Pessimistic Locking`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`Two administrators editing a venue description can use version conflict detection.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T056-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Нормалізація організовує реляційні таблиці для зменшення зайвого повторення та аномалій оновлення.`},{id:`B`,text:`Оптимістичний контроль перевіряє, чи змінилися дані перед фіксацією; песимістичне блокування завчасно резервує доступ.`},{id:`C`,text:`Індекси прискорюють вибіркове читання через допоміжні структури ціною додаткової пам’яті й витрат запису.`},{id:`D`,text:`Еволюція схеми змінює структуру збереження, не втрачаючи даних і сумісності сервісів.`}]},{id:`T056-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Використовуйте EXPLAIN та виміряні трасування; знаходьте full scan, дорогі sort, N+1 ORM-запити й зайві колонки.`},{id:`B`,text:`Застосовуйте expand-migrate-contract: додайте сумісні поля, поступово заповніть, перемкніть читання й запис, а потім приберіть старе після перевірки.`},{id:`C`,text:`Оптимістичний підхід часто використовує колонку version у compare-and-swap оновленні; за конфлікту повертає помилку або повторює зі свіжим станом.`},{id:`D`,text:`1NF вимагає атомарних значень у вибраній реляційній моделі; 2NF прибирає часткову залежність від ключа; 3NF — проблемні транзитивні залежності; BCNF посилює вимоги до детермінантів; 4NF враховує незалежні багатозначні залежності; 5NF — залежності з’єднання.`}]},{id:`T056-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Двоє адміністраторів можуть редагувати опис закладу з перевіркою версії.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`Продаж останнього квитка потребує атомарного умовного оновлення або контрольованого блокування.`},{id:`B`,text:`Обидва сценарії можна реалізувати різними СУБД залежно від деталей.`},{id:`C`,text:`Звірка виправляє розбіжності.`},{id:`D`,text:`Перейменування guest.fullName на firstName і lastName потребує тимчасового writer або mapper, backfill старих записів і перевірки до видалення старого поля.`}]},{id:`T056-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Автоматичний повтор кожного конфлікту може затерти намір користувача; утримання lock під час мережевого виклику створює конкуренцію.`},{id:`B`,text:`Зворотна міграція не завжди безпечна після нових записів.`},{id:`C`,text:`Дублікати полів можуть розходитися за конкуренції або втрати подій.`},{id:`D`,text:`Індекс на кожне поле шкодить запису й споживає пам’ять.`}]},{id:`T056-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Вибір залежить від частоти конфліктів, критичності та тривалості операції.`}]}]},{id:`T056-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Оптимістичне блокування усуває потребу обробляти конфлікти оновлення.`}]}]},{id:`T056-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Ізоляція транзакцій теж має значення.`}]}]},{id:`T056-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Оптимістичний контроль перевіряє, чи змінилися дані перед фіксацією; песимістичне блокування завчасно резервує доступ.`},{id:`B`,text:`Песимістичне блокування ніколи не спричиняє дедлоків чи очікувань.`},{id:`C`,text:`Оптимістичний підхід часто використовує колонку version у compare-and-swap оновленні; за конфлікту повертає помилку або повторює зі свіжим станом.`},{id:`D`,text:`Додавання індексу завжди прискорює і читання, і запис.`}]},{id:`T056-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Ізоляція транзакцій теж має значення.`},{id:`B`,text:`Оптимістичне блокування усуває потребу обробляти конфлікти оновлення.`},{id:`C`,text:`Продаж останнього квитка потребує атомарного умовного оновлення або контрольованого блокування.`},{id:`D`,text:`Поступові релізи ніколи не потребують стратегії expand-and-contract для схеми.`}]},{id:`T056-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Двоє адміністраторів можуть редагувати опис закладу з перевіркою версії.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента порівняти плани запиту до й після індексів доступності номерів. Вимагайте замір затримки, вартості запису та план відкату.`},{id:`B`,text:`Попросіть агента реалізувати оновлення за версією та бронювання з блокуванням. Перевірте конфлікти, deadlock і спосіб розв’язання для користувача.`},{id:`C`,text:`Попросіть агента оптимізувати сторінку товару похідною кількістю оцінок. Визначте семантику оновлення, відновлення та тести повторених чи затриманих подій.`},{id:`D`,text:`Попросіть агента спланувати розділення колонки без простою: етапи релізу, контрольні точки backfill, перевірки цілісності, межі rollback і метрики.`}]},{id:`T056-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Коли конфлікт потрібно показати користувачу, а не повторювати автоматично?`}]}]},{id:`T056-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Двоє адміністраторів можуть редагувати опис закладу з перевіркою версії.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T056-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Двоє адміністраторів можуть редагувати опис закладу з перевіркою версії.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T056-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Двоє адміністраторів можуть редагувати опис закладу з перевіркою версії.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T056-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Оптимістичне та песимістичне блокування`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Двоє адміністраторів можуть редагувати опис закладу з перевіркою версії.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var o={slug:i,topicId:56,questions:n};export{o as default,n as questions,i as slug,s as topicId};